);font-size:27px;line-height:1;font-weight:760;letter-spacing:-.035em}.pm-kpi-note{margin-top:auto;color:var(--pm-subtle);font-size:11px}.pm-kpi-primary strong{color:var(--pm-accent)}.pm-content-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(290px,.8fr);gap:16px}.pm-panel{background:#fff!important;border:1px solid var(--pm-border)!important;border-radius:10px!important;box-shadow:none!important;overflow:hidden}.pm-panel-heading{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border-bottom:1px solid var(--pm-border)}.pm-panel-heading h2,.pm-focus-panel h2{margin:2px 0 0;color:var(--pm-ink);font-size:17px;font-weight:720;letter-spacing:-.02em}.pm-panel-heading a,.pm-text-action{color:var(--pm-accent);font-size:12px;font-weight:700;text-decoration:none}.pm-task-row{display:flex;align-items:center;gap:12px;padding:14px 20px;border-bottom:1px solid #f0f2f5}.pm-task-main{min-width:0;flex:1}.pm-task-main strong{font-size:13px;font-weight:650;color:#344054}.pm-task-main span{font-size:11px;color:var(--pm-subtle)}.pm-priority,.pm-status-chip{padding:4px 7px;border-radius:5px;font-size:9px;font-weight:750;text-transform:uppercase;letter-spacing:.04em}.priority-high,.pm-priority-high{background:#fef3f2;color:#b42318}.priority-medium,.pm-priority-medium{background:#fffaeb;color:#b54708}.priority-low,.pm-priority-low{background:#eff8ff;color:#175cd3}.pm-status-chip{background:#f2f4f7;color:#475467}.pm-focus-panel{padding:22px}.pm-focus-panel>p:not(.pm-eyebrow){color:var(--pm-muted);font-size:13px;line-height:1.65}.pm-quick-links{display:flex;flex-direction:column;margin-top:16px}.pm-quick-links a{display:flex;justify-content:space-between;padding:12px 0;border-top:1px solid var(--pm-border);color:#344054;font-size:13px;font-weight:650;text-decoration:none}.pm-quick-links a span{color:var(--pm-accent)}
